// generated by gemini-3.5-flash-lite for PR #5837 (round 0): vector_json_rvalue_moves
// intent: Verify that an rvalue vector of json objects moves elements properly during conversion.
#include <nlohmann/json.hpp>
#include <iostream>
#include <vector>

int main() {
    std::vector<nlohmann::json> vj;
    vj.push_back(nlohmann::json(1));
    vj.push_back(nlohmann::json(2));
    nlohmann::json j = std::move(vj);
    std::cout << "json: " << j.dump() << std::endl;
    std::cout << "vj size: " << vj.size() << std::endl;
    return 0;
}
